import { drizzle } from "drizzle-orm/d1";
import * as schema from "./schema";

/**
 * Create a Drizzle client backed by the D1 binding `env.DB`.
 *
 * Each request should call this with its own `env` so that the queries run
 * against the worker's request-scoped database binding.
 */
export const createDb = (env: { DB: D1Database }) =>
  drizzle(env.DB, { schema });

export { schema };

import type { Post } from "@/db/schema";

/**
 * Blog index page that lists every post.
 *
 * For each post we render an anchor whose visible text contains the post's
 * `title` and whose `href` is the slug-based dynamic route `/blog/<slug>`.
 */
export const BlogIndex = ({ posts }: { posts: Post[] }) => {
  return (
    <main>
      <h1>Blog</h1>
      {posts.length === 0 ? (
        <p>No posts yet.</p>
      ) : (
        <ul>
          {posts.map((post) => (
            <li key={post.id}>
              <a href={`/blog/${post.slug}`}>{post.title}</a>
            </li>
          ))}
        </ul>
      )}
      <p>
        <a href="/">← Home</a>
      </p>
    </main>
  );
};

import type { Post } from "@/db/schema";

/**
 * Single blog post page.
 *
 * Renders the post's `title` and `content`. Both values must be present in
 * the returned HTML for the dynamic slug route to satisfy the spec.
 */
export const BlogPost = ({ post }: { post: Post }) => {
  return (
    <main>
      <article>
        <h1>{post.title}</h1>
        <div>
          {post.content.split(/\n{2,}/).map((paragraph, idx) => (
            <p key={idx}>{paragraph}</p>
          ))}
        </div>
      </article>
      <p>
        <a href="/blog">← Back to all posts</a>
      </p>
    </main>
  );
};

import { eq } from "drizzle-orm";
import { render, route } from "rwsdk/router";
import { defineApp } from "rwsdk/worker";

import { Document } from "@/app/document";
import { setCommonHeaders } from "@/app/headers";
import { BlogIndex } from "@/app/pages/blogIndex";
import { BlogPost } from "@/app/pages/blogPost";
import { Home } from "@/app/pages/home";
import { createDb } from "@/db/client";
import { posts } from "@/db/schema";

export type AppContext = {
  db: ReturnType<typeof createDb>;
};

export default defineApp([
  setCommonHeaders(),
  async ({ ctx, request }) => {
    // Make the Drizzle client available on the context for downstream routes.
    ctx.db = createDb((request as unknown as { env: Env }).env);
  },
  render(Document, [
    route("/", Home),

    // Blog index — lists every post persisted in D1.
    route("/blog", async ({ ctx, request }) => {
      const env = (request as unknown as { env: Env }).env;
      const db = createDb(env);
      const rows = await db.select().from(posts).all();
      return <BlogIndex posts={rows} />;
    }),

    // Dynamic slug route — looks up a single post by slug and renders it.
    // Returns 404 when no post matches.
    route("/blog/:slug", async ({ params, request }) => {
      const env = (request as unknown as { env: Env }).env;
      const db = createDb(env);
      const row = await db
        .select()
        .from(posts)
        .where(eq(posts.slug, params.slug))
        .get();

      if (!row) {
        return new Response("Post not found", {
          status: 404,
          headers: { "Content-Type": "text/html; charset=utf-8" },
        });
      }

      return <BlogPost post={row} />;
    }),
  ]),
]);

